from sys import stdin, stdout
import math

def choose(n, k):
    if k > n:
        return 0
    if k == 0 or k == n:
        return 1
    return (choose(n-1, k-1) + choose(n-1, k)) % (10**6 + 7)

def solve(N, M, K):
    total_ways = 0
    for i in range(1, min(K, M*N//N)+1):
        ways_to_choose_i = choose(M, i)
        remaining_k = K - i * N
        if remaining_k >= 0:
            ways_to_choose_remaining = choose(M, remaining_k // i) if i != 1 else 1
            total_ways = (total_ways + ways_to_choose_i * ways_to_choose_remaining) % (10**6 + 7)
    return total_ways

if __name__ == "__main__":
    N, M, K = map(int, stdin.readline().split())
    result = solve(N, M, K)
    stdout.write(str(result) + '\n')

import math

def calculate_ways(N, M, K):
    MOD = 10**6 + 7
    def comb(n, k):
        if k > n:
            return 0
        return math.factorial(n) // (math.factorial(k) * math.factorial(n - k))

    total_ways = 0
    for i in range(K + 1):
        if i % 2 == 0:
            total_ways += comb(M, i) * pow(comb(N, i // 2), 2)
        else:
            total_ways -= comb(M, i) * comb(N, i // 2)
        total_ways %= MOD

    return total_ways

if __name__ == "__main__":
    import sys
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    M = int(data[1])
    K = int(data[2])
    result = calculate_ways(N, M, K)
    print(result)
